
import re, os, pymysql
DB = "mydatabase"
files = ['customer', 'device', 'firmwaremetadata', 'manufacturer', 'submit_block_record']
stmts = ['CREATE TABLE IF NOT EXISTS `mydatabase`.`customer` (\n  `customer_id` char(36) NOT NULL,\n  `name` varchar(255) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `customer_cert` blob NOT NULL,\n  `manufacturer_id` char(36) NOT NULL,\n  PRIMARY KEY (`customer_id`),\n  KEY `idx_manufacturer_id` (`manufacturer_id`),\n  CONSTRAINT `fk_customer_manufacturer` FOREIGN KEY (`manufacturer_id`) REFERENCES `mydatabase`.`manufacturer` (`manufacturer_id`) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci', 'CREATE TABLE IF NOT EXISTS `mydatabase`.`device` (\n  `manufacturer_id` char(36) NOT NULL,\n  `device_type` varchar(100) NOT NULL,\n  PRIMARY KEY (`device_type`,`manufacturer_id`),\n  KEY `fk_device_manufacturer` (`manufacturer_id`),\n  CONSTRAINT `fk_device_manufacturer` FOREIGN KEY (`manufacturer_id`) REFERENCES `mydatabase`.`manufacturer` (`manufacturer_id`) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci', 'CREATE TABLE IF NOT EXISTS `mydatabase`.`firmwaremetadata` (\n  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,\n  `metadata_signature` varbinary(512) NOT NULL,\n  `metadata_signature_algorithm` varchar(255) NOT NULL,\n  `firmware_signature` varbinary(512) NOT NULL,\n  `firmware_signature_algorithm` varchar(255) NOT NULL,\n  `firmware_size` bigint(20) unsigned NOT NULL,\n  `release_date` bigint(20) NOT NULL,\n  `manufacturer_id` char(36) NOT NULL,\n  `device_type` varchar(100) NOT NULL,\n  `firmware_version` varchar(50) NOT NULL,\n  `firmware_data` longblob NOT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `firmware_version` (`firmware_version`),\n  KEY `FK_firmwaremetadata_device` (`manufacturer_id`,`device_type`),\n  CONSTRAINT `FK_firmwaremetadata_device` FOREIGN KEY (`manufacturer_id`, `device_type`) REFERENCES `mydatabase`.`device` (`manufacturer_id`, `device_type`) ON DELETE NO ACTION ON UPDATE NO ACTION\n) ENGINE=InnoDB AUTO_INCREMENT=3007 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci', 'CREATE TABLE IF NOT EXISTS `mydatabase`.`manufacturer` (\n  `manufacturer_id` char(36) NOT NULL,\n  `manufacturer_name` varchar(255) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `manufacturer_cert` blob NOT NULL,\n  PRIMARY KEY (`manufacturer_id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci', 'CREATE TABLE IF NOT EXISTS `mydatabase`.`submit_block_record` (\n  `object_id` varchar(66) NOT NULL,\n  `metadata_id` bigint(20) unsigned NOT NULL,\n  `submit_block_result` text NOT NULL,\n  PRIMARY KEY (`object_id`) USING BTREE,\n  UNIQUE KEY `idx_block_id` (`object_id`) USING BTREE,\n  KEY `idx_metadata_id` (`metadata_id`),\n  CONSTRAINT `fk_submit_block_metadata` FOREIGN KEY (`metadata_id`) REFERENCES `mydatabase`.`firmwaremetadata` (`id`) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci']
# root password 由 compose 注入 (DB_INIT_PASSWORD; 亦可用 MYSQL_ROOT_PASSWORD)
_root_pw = os.environ.get("DB_INIT_PASSWORD") or os.environ.get("MYSQL_ROOT_PASSWORD")
conn = pymysql.connect(host="mariadb", port=3306, user="root", password=_root_pw)
cur = conn.cursor()
for s in stmts:
    try:
        cur.execute(s); conn.commit(); print("OK :", s[:60])
    except Exception as e:
        conn.rollback(); print("ERR:", str(e)[:60])
cur.execute("SHOW TABLES IN mydatabase")
print("container mydatabase:", [r[0] for r in cur.fetchall()])
